========================================= */
/* 当气泡内包含图片、视频、图片容器、转账卡片、位置卡片、长图卡片、礼物盒时，隐藏所有装饰 */
.bubble-me-custom:has(img, video, .msg-image-wrapper, .msg-transfer-card, .msg-loc-card, .msg-sim-card, .gift-ig-container)::before,
.bubble-me-custom:has(img, video, .msg-image-wrapper, .msg-transfer-card, .msg-loc-card, .msg-sim-card, .gift-ig-container)::after,
.bubble-them-custom:has(img, video, .msg-image-wrapper, .msg-transfer-card, .msg-loc-card, .msg-sim-card, .gift-ig-container)::before,
.bubble-them-custom:has(img, video, .msg-image-wrapper, .msg-transfer-card, .msg-loc-card, .msg-sim-card, .gift-ig-container)::after {
  display: none !important;
}
/* ================================================
 * 消息间距微调
 * ================================================ */
.chat-message-list-custom .msg-bubble-container {
  margin-bottom: 1px !important;
}
.bubble-me-custom.first,
.bubble-them-custom.first {
  margin-top: 5px;
}
/* 当气泡内包含：图片(含表情包)、视频、图片容器、转账卡片、位置卡片、长图卡片、礼物盒 时，强制背景透明并去掉内边距 */
.bubble-me-custom:has(img, video, .msg-image-wrapper, .msg-transfer-card, .msg-loc-card, .msg-sim-card, .gift-ig-container),
.bubble-them-custom:has(img, video, .msg-image-wrapper, .msg-transfer-card, .msg-loc-card, .msg-sim-card, .gift-ig-container) {
  background-color: transparent !important;
  background: transparent !important;
  padding: 0 !important;
  border: none !important;
  box-shadow: none !important;
}
/* 当气泡内包含图片、视频、转账卡片、位置卡片、长图卡片、礼物盒、电话卡片时，隐藏装饰贴图（::before 和 ::after） */
.bubble-me-custom:has(img, video, .msg-image-wrapper, .msg-transfer-card, .msg-loc-card, .msg-sim-card, .gift-ig-container, .msg-phone-card, [class*="call"], [class*="phone"])::before,
.bubble-me-custom:has(img, video, .msg-image-wrapper, .msg-transfer-card, .msg-loc-card, .msg-sim-card, .gift-ig-container, .msg-phone-card, [class*="call"], [class*="phone"])::after,
.bubble-them-custom:has(img, video, .msg-image-wrapper, .msg-transfer-card, .msg-loc-card, .msg-sim-card, .gift-ig-container, .msg-phone-card, [class*="call"], [class*="phone"])::before,
.bubble-them-custom:has(img, video, .msg-image-wrapper, .msg-transfer-card, .msg-loc-card, .msg-sim-card, .gift-ig-container, .msg-phone-card, [class*="call"], [class*="phone"])::after {
  display: none !important;
}
:root {
  /* 消息之间的时间戳颜色 */
  --timestamp-color: rgba(110, 129, 159, 0.7); /* 对应 #6E819F 的半透明 */

  /* 日期分隔线（今天/昨天） */
  --date-divider-bg: rgba(110, 129, 159, 0.1); /* 极淡的灰蓝背景 */
  --date-divider-color: #6E819F;

  /* 系统提示消息（如果有） */
  --system-msg-bg: rgba(110, 129, 159, 0.05);
  --system-msg-color: #6E819F;
}
:root {
  /* IG/QQ模式下的已读颜色 */
  --status-read-color: #6E819F; 
  --status-color: rgba(110, 129, 159, 0.5); /* 未读/已送达用浅一点的颜色 */

  /* 对方打字指示器的点点颜色 */
  --typing-dot-color: #6E819F;
  --typing-bg: #ffffff; /* 打字气泡的底色 */
}
:root {
  --input-box-bg: #ffffff;
  --input-box-radius: 20px; /* 保持圆润 */
  --input-box-border: 1px solid rgba(110, 129, 159, 0.15); /* 加一圈极细的灰蓝边框 */
  --input-caret-color: #6E819F; /* 把打字时光标闪烁的颜色也改成灰蓝色！ */
}
:root {
  /* 旁白文字设定 */
  --narration-color: #8A97AD; /* 比主题灰蓝稍微浅一点点 */
  --narration-style: normal;  /* 取消默认的斜体，看起来更干净 */
  --narration-size: 0.85em;
  --narration-weight: 300;
}
/* 给旁白左右加上精致的十字星或短划线 */
.msg-narration-custom::before {
  content: '✧';
  margin-right: 8px;
  color: rgba(110, 129, 159, 0.4);
}
.msg-narration-custom::after {
  content: '✧';
  margin-left: 8px;
  color: rgba(110, 129, 159, 0.4);
}
:root {
  /* 我方回复框（在灰蓝底色上） */
  --reply-me-bg: rgba(255, 255, 255, 0.15); 
  --reply-me-border-left: 2px solid #ffffff;
  --reply-me-name-color: #ffffff;
  --reply-me-text-color: rgba(255, 255, 255, 0.85);
  --reply-me-radius: 8px;
  /* 对方回复框（在浅灰紫底色上） */
  --reply-them-bg: rgba(110, 129, 159, 0.08);
  --reply-them-border-left: 2px solid #6E819F;
  --reply-them-name-color: #6E819F;
  --reply-them-text-color: rgba(30, 30, 47, 0.7);
  --reply-them-radius: 8px;
}
:root {
  --more-options-bg: rgba(241, 240, 245, 0.85); /* 你的背景色加一点透明 */
  --more-options-blur: blur(25px) saturate(150%); /* 开启高级液态玻璃模糊 */
  --more-options-border: 1px solid rgba(255, 255, 255, 0.6); /* 边缘高光 */
  --more-options-radius: 16px;
  --more-options-color: #6E819F; /* 菜单里的图标和文字颜色 */
  --more-options-shadow: 0 8px 24px rgba(0, 0, 0, 0.06);
}
/* 定义滑入淡入动画 */
@keyframes slideUpFade {
  from { 
    opacity: 0; 
    transform: translateY(12px); /* 初始位置偏下 */
  }
  to { 
    opacity: 1; 
    transform: translateY(0); 
  }
}
/* 应用到所有消息气泡容器上 */
.msg-bubble-wrapper {
  animation: slideUpFade 0.35s cubic-bezier(0.2, 0.8, 0.2, 1) forwards;
}
/* 定义呼吸灯透明度动画 */
@keyframes pulseGlow {
  0%, 100% { opacity: 0.5; }
  50% { opacity: 1; text-shadow: 0 0 4px rgba(110, 129, 159, 0.3); }
}
/* 应用到你写的 ::after 小字上 */
.chat-header-title::after {
  animation: pulseGlow 2.5s ease-in-out infinite;
}
@keyframes slideInFromLeft {
  from { opacity: 0; transform: translateX(-8px); }
  to   { opacity: 1; transform: translateX(0); }
}
:root {
  --translation-animation: slideInFromLeft 0.3s ease;
  --voice-transcription-animation: slideInFromLeft 0.3s ease;
}
:root {
  /* 通用设置：统一圆角和取消边框，保持干净 */
  --transfer-card-radius: 20px;
  --transfer-card-shadow: 0 2px 10px rgba(0, 0, 0, 0.05);
  --transfer-card-border: none;
  /* 💸 我方转账：灰蓝底色，白色文字与图标 */
  --transfer-me-card-bg: #6E819F;
  --transfer-me-icon-bg: #ffffff;
  --transfer-me-amount-color: #ffffff;
  --transfer-me-label-color: rgba(255, 255, 255, 0.8);
  --transfer-me-subtitle-color: rgba(255, 255, 255, 0.5);
  --transfer-me-status-color: rgba(255, 255, 255, 0.9);
  --transfer-me-divider-color: rgba(255, 255, 255, 0.15); /* 淡淡的白色分割线 */
  /* 💸 对方转账：纯白底色（在浅紫灰背景里更清爽），灰蓝文字与图标 */
  --transfer-them-card-bg: #ffffff;
  --transfer-them-icon-bg: #6E819F;
  --transfer-them-amount-color: #6E819F;
  --transfer-them-label-color: #1e1e2f;
  --transfer-them-subtitle-color: rgba(30, 30, 47, 0.5);
  --transfer-them-status-color: #6E819F;
  --transfer-them-divider-color: rgba(0, 0, 0, 0.05); /* 淡淡的灰色分割线 */
}
:root {
  /* 打字时那一闪一闪的光标颜色 */
  --input-caret-color: #6E819F;

  /* 长按消息多选时，左侧打勾框的颜色 */
  --selection-checkbox-checked-bg: #6E819F;
  --selection-checkbox-border: rgba(110, 129, 159, 0.3);
}
/* 复制文字时，光标扫过的背景色（替换掉默认的傻蓝色） */
::selection {
  background-color: rgba(110, 129, 159, 0.25) !important;
  color: inherit !important;
}
/* 只有整个聊天列表的【绝对最后一条】且是【我方发出的】才会显示 */
[data-absolute-last="true"][data-sender="me"] .bubble-me-custom::before {
  content: "刚刚";
  position: absolute;
  /* 挂在气泡左侧或右侧外面 */
  left: -32px; 
  bottom: 2px;
  font-size: 10px;
  color: rgba(110, 129, 159, 0.5);
  font-style: italic;
  pointer-events: none;
  /* 搭配一个小小的滑入动画 */
  animation: slideInFromLeft 0.3s ease forwards;
}
/* 确保不是最后一条时绝对不显示 */
[data-absolute-last="false"] .bubble-me-custom::before {
  display: none !important;
}
/* 弹簧伸缩动画 */
@keyframes springPop {
  0% { transform: scale(0.5); opacity: 0; }
  60% { transform: scale(1.15); opacity: 1; }
  80% { transform: scale(0.95); }
  100% { transform: scale(1); opacity: 1; }
}
/* 当长按弹出的表情面板出现时 */
.reaction-bar {
  transform-origin: bottom center;
  animation: springPop 0.4s cubic-bezier(0.175, 0.885, 0.32, 1.275) forwards;
}
/* 气泡下方已经添加的小表情，挨个跃出 */
.reaction-item {
  animation: springPop 0.3s cubic-bezier(0.175, 0.885, 0.32, 1.275) forwards;
}
/* 带有物理重量感的弹簧坠落动画 */
@keyframes dropAndBounce {
  0% { 
    opacity: 0; 
    transform: translateY(-15px) scale(0.95); 
  }
  60% { 
    opacity: 1; 
    transform: translateY(2px) scale(1.02); /* 砸到底部微微变形 */
  }
  100% { 
    transform: translateY(0) scale(1); /* 稳稳停住 */
  }
}
/* 我方发出的最新消息执行这个“吧嗒”动画 */
[data-absolute-last="true"][data-sender="me"] .msg-bubble-wrapper {
  animation: dropAndBounce 0.4s cubic-bezier(0.34, 1.56, 0.64, 1) forwards;
}
/* 让打字气泡背景使用极其温柔的浅灰紫 */
:root {
  --typing-bg: rgba(110, 129, 159, 0.08);
  --typing-dot-color: #6E819F; /* 统一颜色 */
}
/* 整个打字气泡缓慢呼吸，表示“对方正在深思熟虑” */
@keyframes calmBreathing {
  0%, 100% { opacity: 0.7; }
  50% { opacity: 1; }
}
.msg-streaming .bubble-them-custom,
.msg-bubble-wrapper:has(.typing-indicator) {
  animation: calmBreathing 2s ease-in-out infinite !important;
  border: none !important;
  box-shadow: none !important;
}
:root {
  /* 回复预览栏的左侧粗线和名字颜色 */
  --reply-bar-accent: #6E819F;           
  /* 预览内容的文字颜色 */
  --reply-bar-text-color: rgba(110, 129, 159, 0.7); 
}
/* 默认状态的输入胶囊过渡效果 */
.input-action-bar-custom {
  transition: all 0.3s cubic-bezier(0.2, 0.8, 0.2, 1) !important;
  border: 1px solid transparent !important;
}
/* 当手指点击输入框，准备打字时触发 */
.input-action-bar-custom:has(.input-box-custom:focus) {
  /* 胶囊底色稍微变纯白/变暗（取决于你是否用了暗黑模式），并加一圈灰蓝描边 */
  border-color: rgba(110, 129, 159, 0.4) !important;
  /* 发出温柔的灰蓝高光，包裹住你的输入框 */
  box-shadow: 0 0 0 4px rgba(110, 129, 159, 0.15) !important;
  transform: translateY(-2px); /* 微微上浮一点，防键盘遮挡感 */
}
/* 定义心跳光环向外扩散消散的动画 */
@keyframes avatarOnlinePulse {
  0% { box-shadow: 0 0 0 0 rgba(110, 129, 159, 0.4); }
  70% { box-shadow: 0 0 0 6px rgba(110, 129, 159, 0); }
  100% { box-shadow: 0 0 0 0 rgba(110, 129, 159, 0); }
}
/* 把光环加在对方的头像容器上 */
.msg-avatar-them-inner {
  border: 1.5px solid #F1F0F5 !important; /* 给头像加个跟背景一样的描边，做物理隔离 */
  animation: liquidAvatar 6s ease-in-out infinite, avatarOnlinePulse 3s infinite !important;
}
.msg-avatar-them-inner,
.msg-avatar-them-ghost {
  transition: transform 0.15s cubic-bezier(0.4, 0, 0.2, 1), filter 0.15s ease !important;
}
/* 定义已读状态的绽放动画 */
@keyframes statusBloom {
  0% { transform: scale(0.8) translateY(2px); opacity: 0; filter: blur(2px); }
  50% { transform: scale(1.1) translateY(0); filter: blur(0); }
  100% { transform: scale(1) translateY(0); }
}
/* 劫持 QQ/IG 模式下的已读状态 (.is-read) */
.msg-status-custom.is-read {
  animation: statusBloom 0.5s cubic-bezier(0.34, 1.56, 0.64, 1) forwards !important;
  color: #6E819F !important;
  font-weight: 600 !important;
}
/* 定义底部高频声波伸缩动画 */
@keyframes sonicVibration {
  0% { width: 10%; opacity: 0.3; filter: blur(1px); }
  50% { width: 80%; opacity: 1; filter: blur(0px); }
  100% { width: 15%; opacity: 0.5; filter: blur(1px); }
}
.input-action-bar-custom {
  position: relative;
}
/* 只有在打字时，底部才会出现这条高频震荡线 */
.input-action-bar-custom:has(.input-box-custom:focus:not(:placeholder-shown))::after {
  content: "";
  position: absolute;
  bottom: 0px; 
  left: 50%;
  transform: translateX(-50%);
  height: 2px;
  background: #6E819F;
  border-radius: 2px;
  /* 0.4秒极速循环，模拟高频震动 */
  animation: sonicVibration 0.4s infinite cubic-bezier(0.25, 0.46, 0.45, 0.94);
  box-shadow: 0 -2px 10px rgba(110, 129, 159, 0.8);
  pointer-events: none;
}
/* 针对长按弹出的上下文菜单 (.ig-context-menu) */
@keyframes hapticPop {
  0% { transform: scale(0.8) translateY(10px); opacity: 0; filter: blur(5px); }
  60% { transform: scale(1.05) translateY(-2px); opacity: 1; filter: blur(0); }
  100% { transform: scale(1) translateY(0); opacity: 1; }
}
.ig-context-menu {
  /* 开启极限的背景模糊，隔绝后方视线 */
  backdrop-filter: blur(40px) saturate(200%) !important;
  -webkit-backdrop-filter: blur(40px) saturate(200%) !important;
  /* 加上高光描边，模拟玻璃厚度 */
  border: 1px solid rgba(255, 255, 255, 0.3) !important;
  box-shadow: 0 20px 50px rgba(0, 0, 0, 0.15), inset 0 1px 1px rgba(255, 255, 255, 0.5) !important;

  transform-origin: center bottom;
  animation: hapticPop 0.3s cubic-bezier(0.175, 0.885, 0.32, 1.275) forwards !important;
}
/* ============================================
   修复：隐形触控按钮（强行撑开点击区域）
   ============================================ */
.header-btn-video,
.header-btn-phone {
  visibility: visible !important;
  pointer-events: auto !important;
  opacity: 0 !important;         /* 整体完全透明 */

  /* 👇 核心修复：强行撑开 36x36 像素的点击区域，防止它缩成 0 */
  min-width: 36px !important;
  width: 36px !important;
  height: 36px !important;

  display: flex !important;
  align-items: center !important;
  justify-content: center !important;
}
/* 让里面的图标乖乖占位（反正外面透明了看不见），防止破坏排版 */
.header-btn-video svg,
.header-btn-phone svg {
  display: block !important;
  opacity: 0 !important;
}

:root {
