  /*             顶栏图标 & 头像设定            */
  /* ========================================== */
  /* 替换顶栏按钮贴图 */
  --back-btn-icon: url('https://img.heliar.top/file/1777904860773_retouch_2026050422082256.png');
  --phone-btn-icon: url('https://img.heliar.top/file/1777904855981_retouch_2026050422094801.png');
  --video-btn-icon: url('https://img.heliar.top/file/1777904863876_retouch_2026050422092659.png');
  --info-btn-icon: url('https://img.heliar.top/file/1777904852748_retouch_2026050422100401.png');

  /* --- 调整此处控制顶栏头像的大小 --- */
  --chat-header-avatar-size: 46px; /* 默认约 36px，这里调大到了 46px */

  /* --- 新增：顶栏头像框（颜色与昵称一致） --- */
  --chat-header-avatar-border: 2px solid #7E5E5D; /* 这里的 2px 可以改为 1px 变细或 3px 变粗 */

  /* --- 调整此处控制顶栏的整体高度 --- */
  --chat-header-height: 90px; /* 默认通常是 56px，可根据需要加大或缩小 */

  /* 昵称颜色设定 (与气泡字体的 #7E5E5D 一致) */
  --chat-header-title-color: #7E5E5D;
}

/* ========================================== */
/*             顶栏整体内容上下移动             */
/* ========================================== */
.chat-header-custom > * {
  /* --- 调整此处控制顶栏内所有东西的整体上下偏移 --- */
  transform: translateY(10px); /* 正值整体向下移动，负值整体向上移动，例如：translateY(5px) */
}

/* ========================================== */
/*             顶栏头像旋转动画               */
/* ========================================== */
@keyframes avatar-spin {
  from { transform: rotate(0deg); }
  to { transform: rotate(360deg); }
}
.header-avatar-container {
  /* 5s表示转一圈需要5秒。数字越小转得越快，比如 3s */
  animation: avatar-spin 5s linear infinite; 
  border-radius: 50%; /* 确保头像为正圆形，旋转起来才像唱片 */
}

/* ========================================== */
/*             昵称与下方小字自定义             */
/* ========================================== */
.chat-header-title {
  position: relative;
  /* --- 调整此处单独控制【昵称+小字】的上下左右位置 --- */
  top: 0px;   /* 正值向下移动，负值向上移动 */
  left: 0px;  /* 正值向右移动，负值向左移动 */
}

/* 隐藏原有的可能存在的副标题状态（如“在线”），避免与我们要加的小字重叠 */
.chat-header-subtitle {
  display: none !important;
}

/* 在昵称下方加入小字 */
.chat-header-title::after {
  content: "已听歌5200小时";
  display: block;      /* 强制换行到下方 */
  font-size: 11px;     /* 小字的大小 */
  font-weight: normal; /* 字重 */
  color: #7E5E5D;      /* 小字的颜色 (已改为气泡字体颜色) */
  /* --- 调整此处控制【下方小字】相对昵称的位置 --- */
  margin-top: 4px;     /* 控制离上方昵称的距离 (上下位置) */
  margin-left: 0px;    /* 控制左右位置 (正值往右，负值往左) */
}

/* ========================================== */
/*          顶栏按钮/贴图 细节位置调整        */
/* ========================================== */
/* 使用 translate(左右距离, 上下距离) 控制位置，使用 scale(缩放倍数) 控制大小 */

.header-btn-back {
  /* --- 调整此处控制【返回按钮】位置和大小 --- */
  /* translate(0px, 0px) 正数分别代表向右、向下；scale(1)代表原大小，1.2为放大20% */
  transform: translate(0px, 0px) scale(1.0); 
}

.header-btn-phone {
  /* --- 调整此处控制【电话按钮】位置和大小 --- */
  transform: translate(-10px, 0px) scale(1.0);
}

.header-btn-video {
  /* --- 调整此处控制【视频按钮】位置和大小 --- */
  transform: translate(-10px, 0px) scale(1.0);
}

.header-btn-info {
  /* --- 调整此处控制【设置按钮】位置和大小 --- */
  transform: translate(-10px, 0px) scale(1.0);
}
:root {
  /* --- 气泡基础样式 --- */
  /* 我方气泡 */
  --bubble-me-bg: #ffffff;
  --bubble-me-color: #7E5E5D; /* 文字颜色改为和边框一样 */
  --bubble-me-border: 2px solid #7E5E5D; /* 边框加粗到 2px */
  --bubble-me-font-size: 14px; /* 稍微缩小字体 */
  --bubble-me-padding: 8px 12px; /* 缩小内边距 */
  --bubble-me-radius: 18px; /* 相应调整圆角 */
  --bubble-me-radius-first: 18px 18px 4px 18px; /* 连锁气泡圆角也调整 */
  --bubble-me-radius-mid: 18px 4px 4px 18px;
  --bubble-me-radius-last: 18px 4px 18px 18px;
  --bubble-me-transform: scale(0.95); /* 整体等比例缩小 5% */
  --bubble-me-shadow: none; /* 如果有默认阴影，可以取消 */

  /* 对方气泡 */
  --bubble-them-bg: #ffffff;
  --bubble-them-color: #7E5E5D; /* 文字颜色改为和边框一样 */
  --bubble-them-border: 2px solid #7E5E5D; /* 边框加粗到 2px */
  --bubble-them-font-size: 14px; /* 稍微缩小字体 */
  --bubble-them-padding: 8px 12px; /* 缩小内边距 */
  --bubble-them-radius: 18px; /* 相应调整圆角 */
  --bubble-them-radius-first: 18px 18px 18px 4px; /* 连锁气泡圆角也调整 */
  --bubble-them-radius-mid: 4px 18px 18px 4px;
  --bubble-them-radius-last: 4px 18px 18px 18px;
  --bubble-them-transform: scale(0.95); /* 整体等比例缩小 5% */
  --bubble-them-shadow: none; /* 如果有默认阴影，可以取消 */

  /* --- 气泡旁头像设定 --- */
  --avatar-border: 2px solid #7E5E5D; /* 加入与字体颜色相同的头像框 */

  /* 如果是素净模式，也可以调整相关变量来增加间距，避免装饰重叠 */
  --plain-gap-within-group: 6px;    /* 同一发送者连续气泡间距 */
  --plain-gap-between-groups: 20px; /* 不同发送者之间的间距 */
}

/* 确保气泡内的链接颜色在新的文字颜色下依然可见 */
.bubble-me-custom a {
  color: #0095f6 !important; /* 调整为更亮的蓝色，以便区分 */
}
.bubble-them-custom a {
  color: #0095f6 !important; /* 调整为更亮的蓝色，以便区分 */
}

/* --- 装饰贴图部分 --- */

/* 确保气泡本体是定位父元素，并允许装饰超出边界 */
.bubble-me-custom,
.bubble-them-custom {
  position: relative !important;
  overflow: visible !important; /* 关键：允许装饰贴图超出气泡本身 */
}

/* ---------------------------------------------------- */
/* 我方气泡 (bubble-me-custom) 装饰 */
/* ---------------------------------------------------- */

/* 我方气泡 右下角装饰贴图 */
.bubble-me-custom::after {
  content: "";
  position: absolute;
  width: 10px; /* 贴图宽度，根据需要调整 */
  height: 10px; /* 贴图高度，根据需要调整 */
  bottom: 2px; /* 距离气泡底部的距离，负值表示超出气泡 */
  right: -5px; /* 距离气泡右侧的距离，负值表示超出气泡 */
  background: url("https://img.heliar.top/file/1777868238976_IMG_20260504_121604.png") no-repeat center/contain;
  pointer-events: none; /* 避免装饰图阻挡点击气泡 */
  z-index: 1; /* 确保装饰在气泡内容之上 */
  /* --- 调整此处来控制贴图旋转角度 (deg) --- */
  transform: rotate(19deg); /* 正值顺时针旋转，负值逆时针旋转 */
}

/* 我方气泡 左上角装饰贴图 */
.bubble-me-custom::before {
  content: "";
  position: absolute;
  width: 22px; /* 贴图宽度，根据需要调整 */
  height: 22px; /* 贴图高度，根据需要调整 */
  top: -7px; /* 距离气泡顶部的距离，负值表示超出气泡 */
  left: -5px; /* 距离气泡左侧的距离，负值表示超出气泡 */
  background: url("https://img.heliar.top/file/1777868246148_IMG_20260504_121611.png") no-repeat center/contain;
  pointer-events: none;
  z-index: 1;
  /* --- 调整此处来控制贴图旋转角度 (deg) --- */
  transform: rotate(-10deg); /* 正值顺时针旋转，负值逆时针旋转 */
}

/* ---------------------------------------------------- */
/* 对方气泡 (bubble-them-custom) 装饰 */
/* ---------------------------------------------------- */

