/* ========================================== */
/*               各种酷炫动画                 */
/* ========================================== */

/* 1. 气泡果冻弹跳动画 (发送时像果冻一样弹出) */
@keyframes jelly-pop {
  0% { transform: scale(0.85); opacity: 0; }
  45% { transform: scale(1.02); opacity: 1; }
  70% { transform: scale(0.98); }
  100% { transform: scale(1); }
}
.msg-bubble-wrapper {
  animation: jelly-pop 0.35s cubic-bezier(0.25, 0.8, 0.25, 1) forwards;
  transform-origin: bottom center; /* 从底部弹出的物理感觉 */
}

/* 2. 输入框呼吸灯动画 */
@keyframes input-breathe {
  0% { box-shadow: 0 0 2px rgba(126, 94, 93, 0.1); }
  50% { box-shadow: 0 0 10px rgba(126, 94, 93, 0.5); }
  100% { box-shadow: 0 0 2px rgba(126, 94, 93, 0.1); }
}
.input-action-bar-custom {
  animation: input-breathe 2.5s infinite ease-in-out;
}

/* 3. 旁白浮现动画 */
@keyframes narr-fade-in {
  0% { opacity: 0; transform: translateY(8px); }
  100% { opacity: 1; transform: translateY(0); }
}
.msg-narration-custom {
  animation: narr-fade-in 0.6s ease-out forwards;
}

/* ========================================== */
/*             交互点击反馈 (按下缩小)          */
/* ========================================== */

/* 顶栏返回按钮点击反馈 */
.header-btn-back:active {
  transform: translate(0px, 0px) scale(0.8) !important;
  transition: transform 0.1s ease;
}

/* 顶栏其他三个按钮点击反馈 (保留了之前的 -10px 位移) */
.header-btn-phone:active,
.header-btn-video:active,
.header-btn-info:active {
  transform: translate(-10px, 0px) scale(0.8) !important;
  transition: transform 0.1s ease;
}

/* 底栏的“か”和“よ”点击反馈 (保留了绝对居中的 translateY) */
.input-btn-plus:active,
.input-btn-ai:active {
  transform: translateY(-50%) scale(0.75) !important;
  transition: transform 0.1s ease;
}
/* --- 气泡旁头像的轻微呼吸悬浮 --- */
@keyframes avatar-breathe {
  0%, 100% { transform: translateY(0) scale(1); }
  50% { transform: translateY(-2px) scale(1.05); } /* 稍微上浮并放大一点点 */
}
.msg-avatar-custom,
.msg-avatar-them-inner,
.msg-avatar-me-inner {
  animation: avatar-breathe 4s ease-in-out infinite;
}
/* --- 光标与选中文字变色 --- */
:root {
  --input-caret-color: #7E5E5D; /* 改变打字那根闪烁的线 */
}
/* 改变长按/鼠标选中文本时的底色 */
