}
.input-btn-plus svg, .input-btn-plus img, .input-btn-plus i, .input-btn-plus span, .input-btn-plus::after {
    display: none !important;
}
.input-btn-plus::before {
    content: "" !important;
    position: absolute !important;
    top: 50% !important;
    left: 50% !important;
    transform: translate(-50%, -50%) !important;
    width: var(--plus-icon-size) !important;
    height: var(--plus-icon-size) !important;
    background-image: url(https://nos.netease.com/ysf/a33f541345a15bec624a41217fc82ff9.png) !important;
    background-size: contain !important;
    background-repeat: no-repeat !important;
    background-position: center !important;
