    outline: none !important;
    box-shadow: none !important;
    border-radius: var(--input-bar-border-radius) !important;
    height: var(--input-bar-height) !important;
    min-height: var(--input-bar-height) !important;
    max-height: var(--input-bar-height) !important;
    left:-5px!important;
    display: flex !important;
    align-items: center !important;
    padding: 0 !important;
    position: relative !important;
    margin: 0 8px 0 0 !important;
    box-sizing: border-box !important;
}
.input-box-custom {
    width: 100% !important;
    background: transparent !important;
    border: none !important;
    outline: none !important;
    box-shadow: none !important;
    color: #000000 !important;
    font-size: var(--input-font-size) !important;
    height: var(--input-bar-height) !important;
    min-height: var(--input-bar-height) !important;
    line-height: var(--input-bar-height) !important;
    padding: 0 14px !important;
    margin: 0 !important;
    box-sizing: border-box !important;
    resize: none !important;
    overflow: hidden !important;
}
.input-box-custom:focus {
    outline: none !important;
    box-shadow: none !important;
}
.input-box-custom::placeholder {
    color: transparent !important;
    opacity: 0 !important;
}
.input-action-bar-custom::before {
    content: var(--input-placeholder-text) !important;
    position: absolute !important;
    left: 15px !important;
    top: 50% !important;
    transform: translateY(-50%) !important;
    color: var(--input-placeholder-color) !important;
    font-size: var(--input-font-size) !important;
    pointer-events: none !important;
