    background-size: contain !important;
    background-repeat: no-repeat !important;
    background-position: center !important;
    -webkit-filter: none !important;
    opacity: 1 !important;
    margin-left: var(--ai-btn-margin-left) !important;
    margin-right: var(--ai-btn-margin-right) !important;
}
.input-btn-ai * { display: none !important; }

/* 表情按钮（完全隐藏） */
.input-btn-sticker {
    width: var(--sticker-btn-size) !important;
    height: var(--sticker-btn-size) !important;
    background: transparent !important;
    border: none !important;
    cursor: pointer !important;
    flex-shrink: 0 !important;
    margin-left: 2px !important;
    margin-right: 10px !important;
    background-image: none !important;
}
.input-btn-sticker * { display: none !important; }

/* 麦克风按钮（隐藏图标保留占位，不影响布局） */
.input-btn-mic {
    width: var(--mic-btn-size) !important;
    height: var(--mic-btn-size) !important;
    background: transparent !important;
    border: none !important;
    cursor: pointer !important;
    flex-shrink: 0 !important;
    margin-left: 2px !important;
    margin-right: 15px !important;
    background-image: none !important;
}
.input-btn-mic * { display: none !important; }

/* 隐藏发送按钮 */
.send-btn-custom {
    display: none !important;
}

/* 安全补丁：确保所有按钮可点击，伪元素不干扰点击 */
.input-area-custom *::before,
.input-area-custom *::after,
.input-btn-plus::before,
.input-btn-ai::before {
    pointer-events: none !important;
}
.input-btn-plus,
.input-btn-ai,
.input-btn-sticker,
.input-btn-mic {
    filter: none !important;
    -webkit-filter: none !important;
    box-shadow: none !important;
}
