/* ============================================
   完整聊天界面定制（黑色背景版）
   - 全局背景黑色，无分割线
   - 顶栏：返回金色箭头+金色标题+右侧三个按钮（图片120x50）
   - 底栏：输入框高度18px，图标24px，离底部24px，水平等间距
   - 消息区域：深色适配（文字白色，气泡透明，昵称半透明背景）
   ============================================ */

/* ========== 1. 全局可配置变量（颜色、昵称、尺寸等） ========== */
:root {
    /* ----- 昵称文本内容（请在此修改显示的昵称）----- */
    --me-name: "@Kattenbelletje";      /* 我的昵称 */
    --them-name: "@Qui Rêve";           /* 对方昵称 */

    /* ----- 我的昵称样式（黑色背景版推荐半透蓝白）----- */
    --me-name-bg: rgba(0, 135, 254, 0.25);  /* 我的昵称背景色（半透明蓝色） */
    --me-name-color: #66ccff;               /* 我的昵称文字颜色（亮蓝） */
    --me-name-padding: 2px 14px 2px 8px;    /* 我的昵称内边距 */
    --me-name-radius: 8px;                  /* 我的昵称圆角 */

    /* ----- 对方昵称样式（黑色背景版推荐半透灰白）----- */
    --them-name-bg: rgba(255, 255, 255, 0.15); /* 对方昵称背景色（半透白） */
    --them-name-color: #dddddd;               /* 对方昵称文字颜色（浅灰） */
    --them-name-padding: 4px 14px 4px 10px;   /* 对方昵称内边距 */
    --them-name-radius: 8px;                  /* 对方昵称圆角 */

    /* ----- 昵称字体与定位（一般无需改动）----- */
    --name-font-size: 14px;
    --name-font-weight: 700;
    --name-top: -4px;
    --name-margin-top: 40px;
    --name-id-left: 45px;
    --me-name-id-offset: -5px;

    /* ----- 昵称左侧竖线（仅我的昵称）----- */
    --line-width: 3px;
    --line-height: 20px;
    --line-color: #aaaaaa;      /* 竖线颜色（浅灰） */
    --line-radius: 3px;

    /* ----- 气泡与文字颜色（黑色背景版）----- */
    --bubble-color: #ffffff;               /* 气泡内文字颜色（白色） */
    --bubble-font-size: 11px;              /* 气泡字体大小 */

    /* ----- 时间戳样式（黑色背景版）----- */
    --timestamp-size: 7.5px;
    --timestamp-color: #888888;            /* 时间戳颜色（灰色） */

    /* ----- 翻译文字颜色 ----- */
    --translation-text-color: #aaaaaa;

    /* 以下为原有内部变量（可保留不变） */
    --plain-gap-between-groups: 23px;
    --plain-gap-within-group: 13px;
    --plain-content-max-width: 92%;
    --plain-padding-left-me: 10px;
    --plain-padding-right-me: 10px;
    --plain-padding-left-them: 10px;
    --plain-padding-right-them: 10px;
}

