/* ===== 5. 消息区域核心样式（适配黑色背景） ===== */
/* 消息整体布局 */
.msg-bubble-wrapper {
  width: 100% !important;
  display: flex !important;
  flex-direction: column !important;
  align-items: flex-start !important;
  justify-content: flex-start !important;
}

.msg-content-stack {
  width: 100% !important;
  max-width: 100% !important;
}

.msg-bubble-wrapper:not(:has(.msg-transfer-card)):not(:has(.msg-image-wrapper)):not(:has(.gift-ig-container)) .msg-content-stack {
  width: 100% !important;
  max-width: 100% !important;
}

.msg-bubble-wrapper.msg-me {
