.msg-avatar-them-container, .msg-avatar-me-container, .msg-avatar-container {
  display: none !important;
  width: 0 !important;
  height: 0 !important;
}

/* 气泡背景透明，文字颜色使用变量 */
.bubble-me-custom,
.bubble-them-custom {
  position: relative !important;
  background: transparent !important;
  backdrop-filter: none !important;
  border: none !important;
  box-shadow: none !important;
  padding: 0 6px !important;
  border-radius: 0 !important;
  color: var(--bubble-color) !important;
  font-size: var(--bubble-font-size) !important;
  text-align: left !important;
  display: block !important;
  width: 100% !important;
  max-width: 100% !important;
  word-wrap: break-word !important;
  box-sizing: border-box !important;
}

/* 多媒体卡片类消息无额外内边距 */
.bubble-me-custom:has(.msg-image-wrapper),
.bubble-me-custom:has(.voice-msg),
.bubble-me-custom:has(.gift-ig-container),
.bubble-me-custom:has(.msg-transfer-card),
.bubble-me-custom:has(.msg-loc-card),
.bubble-them-custom:has(.msg-image-wrapper),
.bubble-them-custom:has(.voice-msg),
.bubble-them-custom:has(.gift-ig-container),
.bubble-them-custom:has(.msg-transfer-card),
.bubble-them-custom:has(.msg-loc-card) {
