.msg-me .msg-status-custom {
  font-size: var(--timestamp-size) !important;
  color: var(--timestamp-color) !important;
  margin-top: 2px !important;
  display: block !important;
}

/* ===== 6. 昵称显示（黑色背景适配） ===== */
.msg-them,
.msg-me {
  position: relative;
}

/* 我的昵称（左侧带竖线） */
.msg-me.is-first::before,
.msg-me.is-single::before {
  content: var(--me-name) !important;
  position: absolute !important;
  left: calc(var(--name-id-left) + var(--me-name-id-offset) - 17px) !important;
  top: var(--name-top) !important;
  font-weight: var(--name-font-weight) !important;
  font-size: var(--name-font-size) !important;
  pointer-events: none !important;
  z-index: 5 !important;
  white-space: nowrap !important;
  background: var(--me-name-bg) !important;
  color: var(--me-name-color) !important;
  padding: var(--me-name-padding) !important;
  border-radius: var(--me-name-radius) !important;
  line-height: 1.4 !important;
}
.msg-me.is-first::after,
.msg-me.is-single::after {
  content: '' !important;
  position: absolute !important;
  left: calc(var(--name-id-left) + var(--me-name-id-offset) + 1px - 27px) !important;
  top: calc(var(--name-top) + 2px) !important;
  width: var(--line-width) !important;
  height: var(--line-height) !important;
  background: var(--line-color) !important;
  border-radius: var(--line-radius) !important;
  pointer-events: none !important;
  z-index: 6 !important;
}

/* 对方昵称（左侧无竖线） */
.msg-them.is-first::before,
.msg-them.is-single::before {
  content: var(--them-name) !important;
  position: absolute !important;
  left: 14px !important;
  right: 12px !important;
  width: 340px !important;
  top: calc(var(--name-top) - 2px) !important;
  font-weight: var(--name-font-weight) !important;
  font-size: var(--name-font-size) !important;
  pointer-events: none !important;
  z-index: 5 !important;
  background: var(--them-name-bg) !important;
  color: var(--them-name-color) !important;
  padding: var(--them-name-padding) !important;
  border-radius: var(--them-name-radius) !important;
  white-space: normal !important;
  word-break: break-word !important;
  line-height: 1.4 !important;
  box-sizing: border-box !important;
}

/* 不是第一条/单条消息时隐藏昵称和竖线 */
.msg-me:not(.is-first):not(.is-single)::before,
.msg-me:not(.is-first):not(.is-single)::after,
.msg-them:not(.is-first):not(.is-single)::before,
.msg-them:not(.is-first):not(.is-single)::after {
  display: none !important;
  content: none !important;
}

/* 有昵称时消息气泡的上边距 */
.msg-me.is-first .msg-bubble-container,
.msg-me.is-single .msg-bubble-container,
.msg-them.is-first .msg-bubble-container,
.msg-them.is-single .msg-bubble-container {
  margin-top: var(--name-margin-top) !important;
}
.msg-me:not(.is-first):not(.is-single) .msg-bubble-container,
.msg-them:not(.is-first):not(.is-single) .msg-bubble-container {
  margin-top: 0 !important;
}

