/* ===== 昵称样式配置（在下方修改变量即可） ===== */
/* 所有昵称相关的颜色、文本、尺寸、位置等均可在此处修改 */
:root {
    /* ----- 1. 昵称文本内容 ----- */
    --me-name: "@Kattenbelletje";      /* 我的昵称 */
    --them-name: "@Qui Rêve";           /* 对方昵称 */

    /* ----- 2. 我的昵称样式 ----- */
    --me-name-bg: rgba(254, 223, 229, 0.65);  /* 我的昵称背景色（支持透明度） */
    --me-name-color: #FF2D55;                 /* 我的昵称文字颜色 */
    --me-name-padding: 2px 14px 2px 8px;      /* 我的昵称内边距 */
    --me-name-radius: 8px;                    /* 我的昵称圆角 */

    /* ----- 3. 对方昵称样式 ----- */
    --them-name-bg: #E9E9E9;                  /* 对方昵称背景色 */
    --them-name-color: #000000;               /* 对方昵称文字颜色 */
    --them-name-padding: 4px 14px 4px 10px;   /* 对方昵称内边距 */
    --them-name-radius: 8px;                  /* 对方昵称圆角 */

    /* ----- 4. 昵称字体与位置 ----- */
    --name-font-size: 14px;                   /* 昵称字体大小 */
    --name-font-weight: 700;                  /* 昵称字体粗细 */
    --name-top: -4px;                         /* 昵称垂直偏移 */
    --name-margin-top: 40px;                  /* 有昵称时消息气泡的上边距 */
    --name-id-left: 45px;                     /* 我的昵称左侧定位基准 */
    --me-name-id-offset: -5px;                /* 我的昵称左侧微调 */

    /* ----- 5. 昵称左侧竖线（仅我的昵称）----- */
    --line-width: 3px;                        /* 竖线宽度 */
    --line-height: 20px;                      /* 竖线高度 */
    --line-color: #C5C5C7;                    /* 竖线颜色 */
    --line-radius: 3px;                       /* 竖线圆角 */

    /* 以下为原有其他变量（不影响昵称配置） */
    --plain-gap-between-groups: 23px;
    --plain-gap-within-group: 13px;
    --plain-content-max-width: 92%;
    --plain-padding-left-me: 10px;
    --plain-padding-right-me: 10px;
    --plain-padding-left-them: 10px;
    --plain-padding-right-them: 10px;
    --bubble-color: #000000;
    --bubble-font-size: 11px;
    --timestamp-size: 7.5px;
    --timestamp-color: #ffffff;
    --translation-text-color: #aaaaaa;
}

