/* ================================================
   iOS 26 iMessage 气泡风格（纯色实心，无磨砂）
   统一圆角
   尾巴与气泡同色，垫在气泡下层
   ================================================ */

/* 全局气泡容器需允许伪元素溢出，并建立层叠上下文 */
.bubble-me-custom,
.bubble-them-custom {
  position: relative !important;
  overflow: visible !important;
  isolation: isolate !important;
}

/* ---------- 我方气泡变量（#0090ff 纯色实心）---------- */
:root {
  /* 气泡外观 - 纯色实心 */
  --bubble-me-bg: #f3f3f3;
  --bubble-me-color: #000000;
  --bubble-me-radius: 20px;
  --bubble-me-padding: 8px 16px;
  --bubble-me-font-size: 16px;
  --bubble-me-line-height: 1.4;

  /* 我方小尾巴 */
  --tail-me-url: url("https://i.postimg.cc/NjkgytZR/IMG-2285.png");
  --tail-me-width: 17px;
  --tail-me-height: 20px;
  --tail-me-right: 5px;
  --tail-me-bottom: -10px;
  --tail-me-opacity: 1;
}

/* 我方气泡 - 纯色实心，无磨砂，无边框 */
.bubble-me-custom {
  background: var(--bubble-me-bg) !important;
  color: var(--bubble-me-color) !important;
  padding: var(--bubble-me-padding) !important;
  font-size: var(--bubble-me-font-size) !important;
  line-height: var(--bubble-me-line-height) !important;
  border: none !important;
  border-radius: var(--bubble-me-radius) !important;
  position: relative !important;
  z-index: 2 !important;
  /* 无 backdrop-filter，无 opacity */
}

/* 我方小尾巴 - 垫在气泡下层 */
.bubble-me-custom.single::before,
.bubble-me-custom.last::before {
  content: "";
  position: absolute;
  right: var(--tail-me-right);
  bottom: var(--tail-me-bottom);
  width: var(--tail-me-width);
  height: var(--tail-me-height);
  background-color: #f3f3f3 !important;
  mask: var(--tail-me-url) no-repeat center/contain;
  -webkit-mask: var(--tail-me-url) no-repeat center/contain;
  opacity: var(--tail-me-opacity);
  pointer-events: none;
  z-index: 1;
  /* 无 backdrop-filter */
}

/* 我方连发的第一条、中间条不显示尾巴 */
.bubble-me-custom.first::before,
.bubble-me-custom.mid::before {
  display: none;
}

/* ---------- 对方气泡变量（#e9e9e9 纯色实心，黑色文字）---------- */
:root {
  --bubble-them-bg: #000000;
  --bubble-them-color: #ffffff;
  --bubble-them-radius: 20px;
  --bubble-them-padding: 8px 16px;
  --bubble-them-font-size: 16px;
  --bubble-them-line-height: 1.4;

  /* 对方小尾巴 */
  --tail-them-url: url("https://i.postimg.cc/3J6LgDQW/IMG-2286.png");
  --tail-them-width: 17px;
  --tail-them-height: 20px;
  --tail-them-left: 5px;
  --tail-them-bottom: -10px;
  --tail-them-opacity: 1;
}

/* 对方气泡 - 纯色实心，无磨砂，无边框 */
.bubble-them-custom {
  background: var(--bubble-them-bg) !important;
  color: var(--bubble-them-color) !important;
  padding: var(--bubble-them-padding) !important;
  font-size: var(--bubble-them-font-size) !important;
  line-height: var(--bubble-them-line-height) !important;
  border: none !important;
  border-radius: var(--bubble-them-radius) !important;
  position: relative !important;
  z-index: 2 !important;
  /* 无 backdrop-filter，无 opacity */
}

/* 对方小尾巴 - 垫在气泡下层 */
.bubble-them-custom.single::before,
.bubble-them-custom.last::before {
  content: "";
  position: absolute;
  left: var(--tail-them-left);
  bottom: var(--tail-them-bottom);
  width: var(--tail-them-width);
  height: var(--tail-them-height);
  background-color: #000000 !important;
  mask: var(--tail-them-url) no-repeat center/contain;
  -webkit-mask: var(--tail-them-url) no-repeat center/contain;
  opacity: var(--tail-them-opacity);
  pointer-events: none;
  z-index: 1;
  /* 无 backdrop-filter */
}

/* 对方连发的第一条、中间条不显示尾巴 */
.bubble-them-custom.first::before,
.bubble-them-custom.mid::before {
  display: none;
}

/* ========== 消息间距调整 ========== */
.msg-me,
.msg-them {
  margin-bottom: 2px;
}
.msg-me.last,
.msg-them.last {
