/* === 全局背景色设置 === */
:root {
    --chat-bg-color: #c3d6f1;
}

/* 直接覆盖聊天区域背景 */
.chat-detail-screen,
.chat-messages-area,
[data-theme-style=&quot;plain&quot;] .chat-messages-area {
    background-color: #c3d6f1!important;
}

/* === 1. 基础颜色与布局 (已按新要求更新) === */
:root {
    /* 我方气泡颜色和圆角 */
    --bubble-me-bg: #eaeef7;
    --bubble-me-color: #000000;
    --bubble-me-radius: 18px;

    /* 对方气泡颜色和圆角 */
    --bubble-them-bg: #FFFFFF;
    --bubble-them-color: #000000;
    --bubble-them-radius: 18px;

    /* 连续气泡间的微小间距 */
    --plain-gap-within-group: 4px;

    /* 其他布局保持不变 */
    --plain-gap-between-groups: 16px;
    --plain-avatar-radius: 10px;
    --plain-avatar-size: 36px;
}

/* === 2. 头像显示逻辑 (只在第一条显示) === */
/* 默认隐藏所有头像容器 */
.msg-avatar-them-container,
.msg-avatar-me-container {
    visibility: hidden;
    width: 0;
}

/* 只在“第一条” (is-first) 或 “单条” (is-single) 时显示头像 */
.msg-avatar-them-container.is-first,
.msg-avatar-them-container.is-single,
.msg-avatar-me-container.is-first,
.msg-avatar-me-container.is-single {
    visibility: visible;
    width: var(--plain-avatar-size);
}

/* === 3. 气泡小尾巴 (终极增强版) === */
/* 确保气泡容器允许内容溢出，并且为伪元素提供定位参考 */
.bubble-me-custom,
.bubble-them-custom { 
    position: relative !important; 
    overflow: visible !important; 
}


/* 移除消息边框 */
.bubble-me-custom,
.bubble-them-custom {
  border: none !important;
  outline: none !important;
  box-shadow: none !important;
}


/* 对方气泡小尾巴 (白色) */
.msg-them.is-first .bubble-them-custom::before,
.msg-them.is-single .bubble-them-custom::before {
    content: &quot;&quot; !important;
    display: block !important;
    position: absolute !important;
    background-image: url('https://img.heliar.top/file/1775967946804_retouch_2026041212252435.png?v=1') !important;
    background-size: contain;
    background-repeat: no-repeat;
    background-position: center;
    z-index: 2 !important;

    /* 调整大小和位置 */
    width: 12px;
    height: 17px;
    left: -7px;
    top: 1px;
}

/* 我方气泡小尾巴 (绿色) */
.msg-me.is-first .bubble-me-custom::before,
.msg-me.is-single .bubble-me-custom::before {
    content: &quot;&quot; !important;
    display: block !important;
    position: absolute !important;
    background-image: url('https://i.postimg.cc/2yhkZNsd/wei-ming-ming-zuo-pin.png') !important;
    background-size: contain;
    background-repeat: no-repeat;
    background-position: center;
    z-index: 2 !important;

    /* 调整大小和位置 */
    width: 12px;
    height: 17px;
    right: -5px;
