.chat-header-custom .chat-header-avatar,
.glass-header .header-avatar-container {
    display: none !important;
    visibility: hidden !important;
    width: 0 !important;
    opacity: 0 !important;
}

/* === 2. 昵称下方添加小字&quot;귀여워&quot;=== */
.chat-header-title {
    position: relative !important;
    display: inline-flex !important;
    flex-direction: column !important;
    align-items: center !important;
}

.chat-header-title::after {
    content: &quot;귀여워&quot; !important;
    position: absolute !important;
    top: 100% !important;
    left: 50% !important;
    transform: translateX(-50%) !important;
    font-size: 10px !important;
    font-weight: 400 !important;
    color: rgba(0, 0, 0, 0.5) !important;
    white-space: nowrap !important;
    margin-top: 2px !important;
    letter-spacing: 0.5px !important;
}

.header-profile-section {
    position: relative !important;
}

.header-profile-section .chat-header-subtitle {
    display: none !important;
}

/* === 3. 电话和视频按钮 - 显示并替换为自定义图标 === */

/* 电话按钮 - 替换图标 */
.header-action-btn.header-btn-phone,
.header-btn-phone {
    opacity: 1 !important;
    visibility: visible !important;
    display: inline-flex !important;
    pointer-events: auto !important;
    cursor: pointer !important;
    width: 32px !important;
    height: 32px !important;
    background: transparent !important;
    border: none !important;
    box-shadow: none !important;
}

.header-action-btn.header-btn-phone svg,
.header-btn-phone svg {
    display: none !important;
}

.header-action-btn.header-btn-phone,
.header-btn-phone {
    background-image: url('https://img.heliar.top/file/1775991500118_retouch_2026041218543259.png') !important;
    background-size: 21px 22px !important;
    background-repeat: no-repeat !important;
    background-position: center !important;
    background-color: transparent !important;
}

/* 视频按钮 - 替换图标 */
.header-action-btn.header-btn-video,
.header-btn-video {
    opacity: 1 !important;
    visibility: visible !important;
    display: inline-flex !important;
    pointer-events: auto !important;
    cursor: pointer !important;
    width: 32px !important;
    height: 32px !important;
    background: transparent !important;
    border: none !important;
    box-shadow: none !important;
}

.header-action-btn.header-btn-video svg,
.header-btn-video svg {
    display: none !important;
}

.header-action-btn.header-btn-video,
.header-btn-video {
    background-image: url('https://img.heliar.top/file/1775991606321_retouch_2026041218545119.png') !important;
    background-size: 22px 22px !important;
    background-repeat: no-repeat !important;
    background-position: center !important;
    background-color: transparent !important;
}

/* === 4. 顶栏背景透明 === */
.chat-header-custom,
.glass-header,
.chat-detail-screen .chat-header-custom,
.chat-detail-screen .glass-header {
    background: transparent !important;
    background-color: transparent !important;
    background-image: none !important;
    backdrop-filter: none !important;
    -webkit-backdrop-filter: none !important;
    border-bottom: none !important;
    box-shadow: none !important;
}

.chat-header-custom *,
.glass-header * {
    background-color: transparent !important;
}

.chat-header-title,
.chat-header-icon,
.header-btn-back,
.header-action-btn {
    background: transparent !important;
}

/* === 5. 设置键图标替换为指定黑色图片 === */
:root {
    --info-btn-icon: url('https://img.heliar.top/file/1775973694948_retouch_2026041213594209.png') !important;
}

.header-action-btn.header-btn-info svg,
.header-btn-info svg {
    display: none !important;
}

.header-action-btn.header-btn-info,
.header-btn-info {
    background-image: url('https://img.heliar.top/file/1775973694948_retouch_2026041213594209.png') !important;
    background-size: 20px 20px !important;
    background-repeat: no-repeat !important;
    background-position: center !important;
    background-color: transparent !important;
    width: 32px !important;
    height: 32px !important;
    display: inline-flex !important;
    align-items: center !important;
    justify-content: center !important;
    cursor: pointer !important;
    pointer-events: auto !important;
    opacity: 1 !important;
}

.header-action-btn.header-btn-info,
.header-btn-info {
    margin-right: 0 !important;
}

/* === 顶栏布局微调 === */
.chat-header-custom .header-profile-section,
.glass-header .header-profile-section {
    position: relative !important;
    margin-left: 0 !important;
    padding-left: 0 !important;
}

.header-btn-back {
    background: transparent !important;
    opacity: 1 !important;
    visibility: visible !important;
}

.header-actions-right {
    display: flex !important;
    align-items: center !important;
    gap: 8px !important;
}
:root {
    /* 50% 是正圆，0px 是正方形 */
    /* 8px - 12px 是最像现代 App（如微信、小红书）的方圆效果 */
    --plain-avatar-radius: 30px; 
}

:root {
  /* --- 我方气泡 --- */
  --bubble-me-bg: #FBF5F5;
  --bubble-me-color: #A59D95;           /* 文字改为灰褐色（与边框一致） */
  --bubble-me-radius: 20px;
  --bubble-me-border: 1.5px solid #A59D95;
  /* --- 对方气泡 --- */
  --bubble-them-bg: #F7FAFF;
  --bubble-them-color: #A59D95;         /* 文字改为灰褐色（与边框一致） */
  --bubble-them-radius: 20px;
  --bubble-them-border: 1.5px solid #A59D95;
  /* --- 缩小尺寸 + 缩小上下边距 --- */
  --bubble-me-font-size: 14px;
  --bubble-them-font-size: 14px;
  --bubble-me-padding: 4px 12px;        /* 上下边距从8px缩小到4px */
  --bubble-them-padding: 4px 12px;      /* 上下边距从8px缩小到4px */
  /* --- 连续消息完全圆形 --- */
  --bubble-me-radius-first: 20px;
  --bubble-me-radius-mid: 20px;
  --bubble-me-radius-last: 20px;
  --bubble-them-radius-first: 20px;
  --bubble-them-radius-mid: 20px;
  --bubble-them-radius-last: 20px;
}
/* ========== 装饰贴图 ========== */
/* 我方气泡 - 右上角装饰 */
.bubble-me-custom {
  position: relative !important;
  overflow: visible !important;  /* 允许贴图超出气泡边界 */
}
.bubble-me-custom::after {
  content: "";
  position: absolute;
  /* ===== 可调整：贴图位置 ===== */
  top: 2px;        /* 向上偏移（负值越大约靠上） */
  right: -2px;   /* 向右偏移（负值越大约靠右） */
  /* ===== 可调整：贴图大小 ===== */
  width: 10px;     /* 宽度 */
  height: 10px;    /* 高度 */
  /* 贴图地址（我方：粉色心形） */
  background: url("https://img.heliar.top/file/1776532818551_retouch_2026041901200264.png") no-repeat center/contain;
  pointer-events: none;  /* 让贴图不干扰点击 */
  z-index: 2;
}
/* 对方气泡 - 左上角装饰 */
.bubble-them-custom {
  position: relative !important;
  overflow: visible !important;  /* 允许贴图超出气泡边界 */
}
.bubble-them-custom::before {
  content: "";
  position: absolute;
  /* ===== 可调整：贴图位置 ===== */
  top: 2px;        /* 向上偏移 */
  left: -4px;      /* 向左偏移 */
  /* ===== 可调整：贴图大小 ===== */
  width: 12px;     /* 宽度 */
  height: 12px;    /* 高度 */
  /* 贴图地址（对方：蓝色心形） */
  background: url("https://img.heliar.top/file/1776533232255_retouch_2026041901265400.png") no-repeat center/contain;
  pointer-events: none;  /* 让贴图不干扰点击 */
  z-index: 2;
}
/*
 * 时间戳样式：白色背景 + 灰褐色边框 + 居中显示 + 灰褐色文字
 */
:root {
  --timestamp-color: #A59D95;           /* 文字改为灰褐色（与边框一致） */
  --timestamp-size: 11px;
  --timestamp-weight: 400;
  --timestamp-margin: 4px 0 12px;
}
/* 时间戳外层容器居中 */
.timestamp-custom {
  background-color: #ffffff !important;
  border: 1.5px solid #A59D95 !important;
  border-radius: 30px !important;
  padding: 4px 14px !important;
  font-size: 11px !important;
  color: #A59D95 !important;            /* 文字改为灰褐色 */
  line-height: 1.2 !important;

  /* 居中显示 */
  display: table !important;
  margin-left: auto !important;
  margin-right: auto !important;
  text-align: center !important;

  box-shadow: none !important;
}
/* =========================================
   特殊消息（图片/视频/卡片等）自动隐藏装饰
========================================= */
/* 当气泡内包含图片、视频、图片容器、转账卡片、位置卡片、长图卡片、礼物盒时，隐藏所有装饰 */
.bubble-me-custom:has(img, video, .msg-image-wrapper, .msg-transfer-card, .msg-loc-card, .msg-sim-card, .gift-ig-container)::before,
.bubble-me-custom:has(img, video, .msg-image-wrapper, .msg-transfer-card, .msg-loc-card, .msg-sim-card, .gift-ig-container)::after,
.bubble-them-custom:has(img, video, .msg-image-wrapper, .msg-transfer-card, .msg-loc-card, .msg-sim-card, .gift-ig-container)::before,
.bubble-them-custom:has(img, video, .msg-image-wrapper, .msg-transfer-card, .msg-loc-card, .msg-sim-card, .gift-ig-container)::after {
  display: none !important;
}
/* ================================================
 * 消息间距微调
 * ================================================ */
.chat-message-list-custom .msg-bubble-container {
  margin-bottom: 1px !important;
}
.bubble-me-custom.first,
.bubble-them-custom.first {
  margin-top: 5px;
}
/* 当气泡内包含：图片(含表情包)、视频、图片容器、转账卡片、位置卡片、长图卡片、礼物盒 时，强制背景透明并去掉内边距 */
.bubble-me-custom:has(img, video, .msg-image-wrapper, .msg-transfer-card, .msg-loc-card, .msg-sim-card, .gift-ig-container),
.bubble-them-custom:has(img, video, .msg-image-wrapper, .msg-transfer-card, .msg-loc-card, .msg-sim-card, .gift-ig-container) {
  background-color: transparent !important;
  background: transparent !important;
  padding: 0 !important;
  border: none !important;
  box-shadow: none !important;
}
/* 当气泡内包含图片、视频、转账卡片、位置卡片、长图卡片、礼物盒、电话卡片时，隐藏装饰贴图（::before 和 ::after） */
.bubble-me-custom:has(img, video, .msg-image-wrapper, .msg-transfer-card, .msg-loc-card, .msg-sim-card, .gift-ig-container, .msg-phone-card, [class*="call"], [class*="phone"])::before,
.bubble-me-custom:has(img, video, .msg-image-wrapper, .msg-transfer-card, .msg-loc-card, .msg-sim-card, .gift-ig-container, .msg-phone-card, [class*="call"], [class*="phone"])::after,
.bubble-them-custom:has(img, video, .msg-image-wrapper, .msg-transfer-card, .msg-loc-card, .msg-sim-card, .gift-ig-container, .msg-phone-card, [class*="call"], [class*="phone"])::before,
.bubble-them-custom:has(img, video, .msg-image-wrapper, .msg-transfer-card, .msg-loc-card, .msg-sim-card, .gift-ig-container, .msg-phone-card, [class*="call"], [class*="phone"])::after {
  display: none !important;
}
/* ========== 顶部导航栏定制（昵称完美居中 + 描边效果 + 底部虚线） ========== */
:root {
  /* 顶栏背景：我方气泡颜色 (#FBF5F5) */
  --chat-header-bg: #FBF5F5;
  --chat-header-blur: 0px;
 --chat-header-height: 90px; 
 /* 顶栏边框变量设为透明，交由下面的 class 直接控制 */
  --chat-header-border: transparent;
  /* 昵称样式：颜色与气泡文字一致 (#A59D95) */
  --chat-header-title-color: #A59D95;
  --chat-header-title-size: 17px;
  --chat-header-title-weight: 500;
}
/* 1. 只隐藏头像，不隐藏昵称容器 */
.header-avatar-container {
  display: none !important;
}
/* 2. 强制顶栏使用居中布局 + ✨ 强制底部虚线 ✨ */
.chat-header-custom {
  display: flex !important;
  justify-content: space-between !important;
  align-items: center !important;
  position: relative !important;
  /* 强制设置底部边框为 1.5px 的虚线，颜色同文字颜色 */
  border-bottom: 1.5px dashed #A59D95 !important;
}
/* 3. 让昵称绝对居中（无视左右按钮） */
.header-profile-section {
  position: absolute !important;
  left: 50% !important;
  transform: translateX(-50%) !important;
  display: flex !important;
  justify-content: center !important;
  pointer-events: none !important;
}
/* 4. 昵称本身保持可点击 + ✨ 发光效果 ✨ */
.chat-header-title {
  pointer-events: auto !important;
  /* 添加与文字同色系的柔和发光效果 */
  text-shadow: 0 0 6px rgba(165, 157, 149, 0.6),
               0 0 12px rgba(165, 157, 149, 0.3) !important;
}
/* 5. 昵称前后添加装饰符号 */
.chat-header-title::before {
  content: "ʚ ";
  font-size: inherit;
  color: inherit;
}
.chat-header-title::after {
  content: " ɞ";
  font-size: inherit;
  color: inherit;
}
/* 6. 隐藏电话和视频按钮（保留点击区域） */
.header-btn-phone,
.header-btn-video {
  opacity: 0 !important;
  visibility: visible !important;
  pointer-events: auto !important;
  width: 32px !important;
  display: inline-flex !important;
}
/* 7. 设置按钮：替换为自定义图片 + 描边 */
.header-btn-info svg {
  display: none !important;
}
.header-btn-info {
  background-image: url("https://img.heliar.top/file/1776533849979_retouch_2026041901370818.png") !important;
  background-size: contain !important;
  background-repeat: no-repeat !important;
  background-position: center !important;
  width: 24px !important;
  height: 24px !important;
  filter: drop-shadow(1px 0 0 #A59D95)
          drop-shadow(-1px 0 0 #A59D95)
          drop-shadow(0 1px 0 #A59D95)
          drop-shadow(0 -1px 0 #A59D95) !important;
}
/* 8. 返回按钮：替换为「が」+ 对方气泡颜色 + 描边 */
.header-btn-back svg {
  display: none !important;
}
.header-btn-back {
  background: transparent !important;
  font-size: 20px !important;
  font-weight: 500 !important;
  width: auto !important;
  padding: 0 8px !important;

  /* 文字内容：が */
  content: "が";
  color: #F7FAFF !important;  /* 对方气泡颜色 */

  /* 描边：昵称一样的颜色 (#A59D95) */
  text-shadow: 
    -1px -1px 0 #A59D95,
    1px -1px 0 #A59D95,
    -1px 1px 0 #A59D95,
    1px 1px 0 #A59D95 !important;
}
/* 使用伪元素添加「が」文字 */
.header-btn-back::before {
  content: "が";
  font-size: 20px;
  font-weight: 500;
  color: #F7FAFF;
  text-shadow: 
    -1px -1px 0 #A59D95,
    1px -1px 0 #A59D95,
    -1px 1px 0 #A59D95,
    1px 1px 0 #A59D95;
}
/* 9. 右侧按钮组保持可点击 */
.header-actions-right {
  position: relative !important;
  z-index: 2 !important;
}
/* ========== 底部输入栏定制（描边逻辑全面修正 + 顶部虚线） ========== */
:root {
  /* 底栏背景：对方气泡颜色 */
  --input-area-bg: #F7FAFF;
  --input-area-blur: 0px;
  /* ✨ 底栏边框：改为同文字色的 1.5px 虚线 ✨ */
  --input-area-border-top: 1.5px dashed #A59D95;
  /* 增加上下内边距以弥补输入框缩小的高度，保持底栏总高度不变 */
  --input-area-padding: 12px 12px; 
  --input-area-min-height: 48px;
  /* 输入框：白色背景，缩小高度 */
  --input-box-bg: #ffffff;
  --input-box-color: #333;
  --input-box-placeholder: #bbb;
  --input-box-radius: 20px;
  /* 进一步压低输入框内部文字的上下留白 */
  --input-box-padding: 4px 12px; 
  --input-box-font-size: 14px;
  --input-box-border: 1px solid #ddd;
}
/* 可爱手写字体（系统自带） */
.input-btn-plus,
.input-box-custom {
  font-family: "KaiTi", "华文楷书", "Microsoft YaHei", "STKaiti", "Comic Sans MS", "Chalkboard SE", cursive !important;
}
/* ===== 加号按钮：替换为「ぼ」 ===== */
.input-btn-plus svg {
  display: none !important;
}
.input-btn-plus {
  background: transparent !important;
  font-size: 24px !important;
  font-weight: normal !important;
  width: 36px !important;
  height: 36px !important;
  display: inline-flex !important;
  align-items: center !important;
  justify-content: center !important;
  /* 向上移动一点 */
  transform: translateY(-3px) !important; 
  /* 文字主体：对方气泡颜色 */
  color: #F7FAFF !important;
  /* 描边：气泡内文字颜色 (#A59D95) */
  text-shadow: 
    1px 1px 0 #A59D95,
    -1px -1px 0 #A59D95,
    1px -1px 0 #A59D95,
    -1px 1px 0 #A59D95 !important;
}
.input-btn-plus::before {
  content: "ぼ";
}
/* ===== 语音按钮：完全隐藏，但保留点击区域 ===== */
.input-btn-mic {
  opacity: 0 !important;
  visibility: visible !important;
  pointer-events: auto !important;
  width: 36px !important;
  height: 36px !important;
  display: inline-flex !important;
}
/* ===== 表情按钮：完全隐藏，但保留点击区域 ===== */
.input-btn-sticker {
  opacity: 0 !important;
  visibility: visible !important;
  pointer-events: auto !important;
  width: 36px !important;
  height: 36px !important;
  display: inline-flex !important;
}
.input-btn-sticker svg {
  display: none !important;
}
/* ===== AI 按钮：替换为自定义图片，尺寸缩小，加描边 ===== */
.input-btn-ai svg {
  display: none !important;
}
.input-btn-ai {
  background-image: url("https://img.heliar.top/file/1776535846439_retouch_2026041902102000.png") !important;
  /* 改为具体像素值让贴图变小 */
  background-size: 18px !important; 
  background-repeat: no-repeat !important;
  background-position: center !important;
  background-color: transparent !important;
  /* 容器大小保持 28px 不变，保证点击区域不缩水 */
  width: 28px !important;  
  height: 28px !important;
  display: inline-flex !important;
  /* 图片描边：使用 drop-shadow 模拟四周描边（颜色 #A59D95） */
  filter: drop-shadow(1px 0 0 #A59D95)
          drop-shadow(-1px 0 0 #A59D95)
          drop-shadow(0 1px 0 #A59D95)
          drop-shadow(0 -1px 0 #A59D95) !important;
}
/* 输入框高度微调 */
.input-action-bar-custom {
  /* 让胶囊本体变矮 */
  min-height: 30px !important; 
  /* 去掉多余的留白 */
  padding: 0 !important;       
}
/* 保证底栏背景纯色 */
.input-area-custom {
  background-color: #F7FAFF !important;
  background-image: none !important;
}
/* ✨ 输入框动态呼吸灯光效果 ✨ */
@keyframes breathingLight {
  0% { 
    box-shadow: 0 0 4px rgba(165, 157, 149, 0.2), inset 0 0 2px rgba(165, 157, 149, 0.1); 
    border-color: rgba(165, 157, 149, 0.3); 
  }
  50% { 
    box-shadow: 0 0 14px rgba(165, 157, 149, 0.7), inset 0 0 6px rgba(165, 157, 149, 0.3); 
    border-color: rgba(165, 157, 149, 0.8); 
  }
  100% { 
    box-shadow: 0 0 4px rgba(165, 157, 149, 0.2), inset 0 0 2px rgba(165, 157, 149, 0.1); 
    border-color: rgba(165, 157, 149, 0.3); 
  }
}
/* 将动画绑定到输入框胶囊容器上 */
.input-action-bar-custom {
  animation: breathingLight 3s infinite ease-in-out !important;
}
/* ✨ 2. 气泡Q弹入场动画 ✨ */
@keyframes popInBubble {
  0% { opacity: 0; transform: scale(0.9) translateY(10px); }
  60% { transform: scale(1.02) translateY(-2px); }
  100% { opacity: 1; transform: scale(1) translateY(0); }
}
.msg-bubble-wrapper {
  animation: popInBubble 0.35s cubic-bezier(0.25, 0.8, 0.25, 1) forwards !important;
}
/* ✨ 6. 聊天头像极简边框（无阴影） ✨ */
/* 清除可能自带的阴影变量 */
:root {
  --avatar-shadow: none !important;
}
