:root {
  /* 打字时那一闪一闪的光标颜色 */
  --input-caret-color: #6E819F;

  /* 长按消息多选时，左侧打勾框的颜色 */
  --selection-checkbox-checked-bg: #6E819F;
  --selection-checkbox-border: rgba(110, 129, 159, 0.3);
}
/* 复制文字时，光标扫过的背景色（替换掉默认的傻蓝色） */
::selection {
  background-color: rgba(110, 129, 159, 0.25) !important;
  color: inherit !important;
}
/* 只有整个聊天列表的【绝对最后一条】且是【我方发出的】才会显示 */
[data-absolute-last="true"][data-sender="me"] .bubble-me-custom::before {
  content: "刚刚";
  position: absolute;
  /* 挂在气泡左侧或右侧外面 */
  left: -32px; 
  bottom: 2px;
  font-size: 10px;
  color: rgba(110, 129, 159, 0.5);
  font-style: italic;
  pointer-events: none;
  /* 搭配一个小小的滑入动画 */
  animation: slideInFromLeft 0.3s ease forwards;
}
/* 确保不是最后一条时绝对不显示 */
[data-absolute-last="false"] .bubble-me-custom::before {
  display: none !important;
}
/* 弹簧伸缩动画 */
@keyframes springPop {
  0% { transform: scale(0.5); opacity: 0; }
  60% { transform: scale(1.15); opacity: 1; }
  80% { transform: scale(0.95); }
  100% { transform: scale(1); opacity: 1; }
}
/* 当长按弹出的表情面板出现时 */
.reaction-bar {
  transform-origin: bottom center;
  animation: springPop 0.4s cubic-bezier(0.175, 0.885, 0.32, 1.275) forwards;
}
/* 气泡下方已经添加的小表情，挨个跃出 */
.reaction-item {
  animation: springPop 0.3s cubic-bezier(0.175, 0.885, 0.32, 1.275) forwards;
}
/* 带有物理重量感的弹簧坠落动画 */
@keyframes dropAndBounce {
  0% { 
    opacity: 0; 
    transform: translateY(-15px) scale(0.95); 
  }
  60% { 
    opacity: 1; 
    transform: translateY(2px) scale(1.02); /* 砸到底部微微变形 */
  }
  100% { 
    transform: translateY(0) scale(1); /* 稳稳停住 */
  }
}
/* 我方发出的最新消息执行这个“吧嗒”动画 */
[data-absolute-last="true"][data-sender="me"] .msg-bubble-wrapper {
  animation: dropAndBounce 0.4s cubic-bezier(0.34, 1.56, 0.64, 1) forwards;
}
/* 让打字气泡背景使用极其温柔的浅灰紫 */
:root {
  --typing-bg: rgba(110, 129, 159, 0.08);
  --typing-dot-color: #6E819F; /* 统一颜色 */
}
/* 整个打字气泡缓慢呼吸，表示“对方正在深思熟虑” */
@keyframes calmBreathing {
  0%, 100% { opacity: 0.7; }
  50% { opacity: 1; }
}
.msg-streaming .bubble-them-custom,
.msg-bubble-wrapper:has(.typing-indicator) {
  animation: calmBreathing 2s ease-in-out infinite !important;
  border: none !important;
  box-shadow: none !important;
}
:root {
  /* 回复预览栏的左侧粗线和名字颜色 */
  --reply-bar-accent: #6E819F;           
  /* 预览内容的文字颜色 */
  --reply-bar-text-color: rgba(110, 129, 159, 0.7); 
}
/* 默认状态的输入胶囊过渡效果 */
.input-action-bar-custom {
  transition: all 0.3s cubic-bezier(0.2, 0.8, 0.2, 1) !important;
  border: 1px solid transparent !important;
}
/* 当手指点击输入框，准备打字时触发 */
.input-action-bar-custom:has(.input-box-custom:focus) {
  /* 胶囊底色稍微变纯白/变暗（取决于你是否用了暗黑模式），并加一圈灰蓝描边 */
  border-color: rgba(110, 129, 159, 0.4) !important;
  /* 发出温柔的灰蓝高光，包裹住你的输入框 */
  box-shadow: 0 0 0 4px rgba(110, 129, 159, 0.15) !important;
  transform: translateY(-2px); /* 微微上浮一点，防键盘遮挡感 */
}
/* 定义心跳光环向外扩散消散的动画 */
@keyframes avatarOnlinePulse {
  0% { box-shadow: 0 0 0 0 rgba(110, 129, 159, 0.4); }
  70% { box-shadow: 0 0 0 6px rgba(110, 129, 159, 0); }
  100% { box-shadow: 0 0 0 0 rgba(110, 129, 159, 0); }
}
/* 把光环加在对方的头像容器上 */
.msg-avatar-them-inner {
  border: 1.5px solid #F1F0F5 !important; /* 给头像加个跟背景一样的描边，做物理隔离 */
  animation: liquidAvatar 6s ease-in-out infinite, avatarOnlinePulse 3s infinite !important;
}
.msg-avatar-them-inner,
.msg-avatar-them-ghost {
  transition: transform 0.15s cubic-bezier(0.4, 0, 0.2, 1), filter 0.15s ease !important;
}
/* 定义已读状态的绽放动画 */
@keyframes statusBloom {
  0% { transform: scale(0.8) translateY(2px); opacity: 0; filter: blur(2px); }
  50% { transform: scale(1.1) translateY(0); filter: blur(0); }
  100% { transform: scale(1) translateY(0); }
}
/* 劫持 QQ/IG 模式下的已读状态 (.is-read) */
.msg-status-custom.is-read {
  animation: statusBloom 0.5s cubic-bezier(0.34, 1.56, 0.64, 1) forwards !important;
  color: #6E819F !important;
  font-weight: 600 !important;
}
/* 定义底部高频声波伸缩动画 */
@keyframes sonicVibration {
  0% { width: 10%; opacity: 0.3; filter: blur(1px); }
  50% { width: 80%; opacity: 1; filter: blur(0px); }
  100% { width: 15%; opacity: 0.5; filter: blur(1px); }
}
.input-action-bar-custom {
  position: relative;
}
/* 只有在打字时，底部才会出现这条高频震荡线 */
.input-action-bar-custom:has(.input-box-custom:focus:not(:placeholder-shown))::after {
  content: "";
  position: absolute;
  bottom: 0px; 
  left: 50%;
  transform: translateX(-50%);
  height: 2px;
  background: #6E819F;
  border-radius: 2px;
  /* 0.4秒极速循环，模拟高频震动 */
  animation: sonicVibration 0.4s infinite cubic-bezier(0.25, 0.46, 0.45, 0.94);
  box-shadow: 0 -2px 10px rgba(110, 129, 159, 0.8);
  pointer-events: none;
}
/* 针对长按弹出的上下文菜单 (.ig-context-menu) */
@keyframes hapticPop {
  0% { transform: scale(0.8) translateY(10px); opacity: 0; filter: blur(5px); }
  60% { transform: scale(1.05) translateY(-2px); opacity: 1; filter: blur(0); }
  100% { transform: scale(1) translateY(0); opacity: 1; }
}
.ig-context-menu {
  /* 开启极限的背景模糊，隔绝后方视线 */
  backdrop-filter: blur(40px) saturate(200%) !important;
  -webkit-backdrop-filter: blur(40px) saturate(200%) !important;
  /* 加上高光描边，模拟玻璃厚度 */
  border: 1px solid rgba(255, 255, 255, 0.3) !important;
  box-shadow: 0 20px 50px rgba(0, 0, 0, 0.15), inset 0 1px 1px rgba(255, 255, 255, 0.5) !important;

  transform-origin: center bottom;
  animation: hapticPop 0.3s cubic-bezier(0.175, 0.885, 0.32, 1.275) forwards !important;
}
/* ============================================
   修复：隐形触控按钮（强行撑开点击区域）
   ============================================ */
.header-btn-video,
.header-btn-phone {
  visibility: visible !important;
  pointer-events: auto !important;
  opacity: 0 !important;         /* 整体完全透明 */

  /* 👇 核心修复：强行撑开 36x36 像素的点击区域，防止它缩成 0 */
  min-width: 36px !important;
