/* =========================================
   ✨ 7. 转账卡片定制（扁平长方形 + 专属配色） ✨
========================================= */
:root {
  /* --- 统一形状：扁平长方形 --- */
  --transfer-card-radius: 10px;          /* 将原本圆润的倒角改成小圆角的长方形 */
  --transfer-card-shadow: none;          /* 去掉多余的阴影，保持扁平感 */
  /* --- 我方转账卡片（粉色系） --- */
  --transfer-me-card-bg: #FBF5F5;        /* 背景：我方气泡颜色 */
  --transfer-me-card-border: 1.5px solid #A59D95; /* 边框：统一灰褐色 */
  --transfer-me-icon-bg: #A59D95;        /* 图标底色：灰褐色 */
  --transfer-me-amount-color: #A59D95;   /* 金额数字：灰褐色 */
  --transfer-me-label-color: #A59D95;    /* 标题文字：灰褐色 */
  --transfer-me-subtitle-color: rgba(165, 157, 149, 0.7); /* 副标题半透明 */
  --transfer-me-status-color: rgba(165, 157, 149, 0.9);   /* 底部状态文字 */
  --transfer-me-divider-color: rgba(165, 157, 149, 0.2);  /* 底部横线 */
  /* --- 对方转账卡片（蓝色系） --- */
  --transfer-them-card-bg: #F7FAFF;      /* 背景：对方气泡颜色 */
  --transfer-them-card-border: 1.5px solid #A59D95; /* 边框：统一灰褐色 */
  --transfer-them-icon-bg: #A59D95;      
  --transfer-them-amount-color: #A59D95; 
  --transfer-them-label-color: #A59D95; 
  --transfer-them-subtitle-color: rgba(165, 157, 149, 0.7); 
  --transfer-them-status-color: rgba(165, 157, 149, 0.9);
  --transfer-them-divider-color: rgba(165, 157, 149, 0.2);
}
/* --- 强制压缩高度，让它变得扁平瘦长 --- */
.msg-transfer-card {
  padding: 10px 14px 8px 14px !important;  /* 压缩上下的内边距 */
  min-width: 220px !important;             /* 稍微拉长宽度，视觉上更像长方形 */
}
/* 压缩内部分割线的上下间距，进一步减少整体高度 */
.msg-transfer-card &gt; div:last-child {
  padding-top: 6px !important;
  margin-top: 6px !important;
}
/* =========================================
   ✨ 8. 旁白模式(State)渐显动画（写字感） ✨
========================================= */
/* 定义缓缓浮现的动画 */
@keyframes narrationReveal {
  0% { 
    opacity: 0; 
    transform: translateY(6px); /* 初始稍微靠下 */
    letter-spacing: -1px;       /* 初始字距微微缩紧 */
    filter: blur(2px);          /* 刚开始带一点点模糊（墨水晕开的感觉） */
  }
  100% { 
    opacity: 1; 
    transform: translateY(0); 
    letter-spacing: 0px;        /* 渐渐舒展到正常字距 */
    filter: blur(0px);          /* 完全清晰 */
  }
}
/* 应用到旁白，并统一字体颜色 */
.msg-narration-custom {
  /* 旁白文字颜色也统一为你主题的灰褐色 */
  color: #A59D95 !important;
  font-size: 13px !important;

  /* 持续 1.8秒，模拟一段话慢慢写完的时间，曲线用 ease-out 让结尾变缓 */
  animation: narrationReveal 1.8s ease-out forwards !important;
}

