}

/* ============================================================
   🚨 安全修复补丁（菜单可点击 + 无空白副作用）
   直接追加在原CSS最后
   ============================================================ */

/* ================================
   1. 只修“菜单层级”，不动布局
================================ */
[class*="menu"],
[class*="dropdown"],
[class*="popup"],
[class*="popover"],
[class*="action-sheet"],{
    z-index: 999999 !important;
    position: fixed !important;
    pointer-events: auto !important;
    isolation: isolate !important;
}

/* ================================
   2. 输入栏保持正常层级（关键）
   👉 不降级！避免空白问题
================================ */
.input-area-custom {
    z-index: 200 !important;
    pointer-events: auto !important;
}

/* ================================
   3. 彻底禁止“透明伪元素挡点击”
================================ */
.input-area-custom *::before,
.input-area-custom *::after,
.header-btn-back::before,
.header-btn-back::after,
.header-action-btn::before,
.header-action-btn::after,
.input-btn-plus::before,
.input-btn-plus::after,
.input-btn-ai::before,
.input-btn-ai::after {
    pointer-events: none !important;
}

/* ================================
   4. 防止输入栏误盖弹层（关键但安全）
================================ */
.input-area-custom {
    transform: translateZ(0); /* 仅提升合成层，不影响布局 */
}

/* ================================
   5. 防止聊天内容底部“视觉错位”
   👉 只补高度，不影响结构
================================ */
.message-list-container,
