:root {
  /* ── 对方名字 ── */
  --label-text: "이재민";            /* 🐰🐰 对方气泡上方显示的名字 🐰🐰 */

  /* ── 聊天背景 ── */
  --chat-bg-color: #ffffff;          /* 🐰 聊天背景颜色 */

  /* ── 我方气泡 ── */
  --bubble-me-bg: #f6f6f6;           /* 🐰 我方气泡颜色 */
  --bubble-me-color: #1a1a1a;        /* 🐰 我方气泡文字颜色 */

  /* ── 对方气泡 ── */
  --bubble-them-bg: #97979C;         /* 🐰 对方气泡颜色 */
  --bubble-them-color: #ffffff;      /* 🐰 对方气泡文字颜色 */

  /* ── 顶栏高度 ── */
  --header-height: 80px;             /* 🐰 顶栏高度 */

  /* ── 翻译文字颜色 ── */
  --translation-text-color: #fff;    /* 🐰 翻译文字颜色 */
}

/* 🐰 小尾巴颜色 — 与上方气泡颜色保持一致即可 */
/* 我方小尾巴 */  .bubble-me-custom::after    { background-color: #f6f6f6 !important; }
/* 对方小尾巴 */  .bubble-them-custom::after  { background-color: #97979C !important; }


/* ════════════════════════════════════════════════
   以下为美化主体，一般不需要改动
   ════════════════════════════════════════════════ */

/* --- 基础变量定义 --- */
:root {
  /* 标题 */
  --title-font-size: 16px;
  --title-font-weight: 600;
  --title-top-offset: 20px;
  --title-color: #1a1a1a;
  --subtitle-font-size: 12px;
  --subtitle-top-offset: 0px;
  --subtitle-color: rgba(0, 0, 0, 0.5);

  /* 聊天背景 */
  --chat-messages-padding: 12px 16px;

  /* 气泡通用 */
  --bubble-scale: 0.95;
  --bubble-radius: 15px;
  --bubble-padding: 10px 14px;
  --bubble-max-width: 100%;

  /* 对方气泡 */
  --bubble-them-margin-top: 18px;

  /* 尾巴设置 */
  --tail-me-size: 12px;
  --tail-me-top: 0px;
  --tail-me-right: -3.5px;
  --tail-me-rotate: -15deg;
  --tail-them-size: 12px;
  --tail-them-top: 0px;
  --tail-them-left: -3px;
  --tail-them-rotate: 15deg;

  /* 对方气泡小文字 & 头像 */
  --label-top: -22px;
  --label-left: 0px;
  --label-size: 12px;
  --label-weight: 500;
  --label-color: rgba(0, 0, 0, 0.4);
  --label-font: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  --avatar-them-radius: 15px;    
  --avatar-them-size: 38px;  

  /* 图标尺寸 & 位置调节 */
  --back-size: 52px;              --back-pos-left: -12px;   --back-pos-top: 25px;
  --video-size: 50px;             --video-pos-right: 30px;  --video-pos-top: -5px;
  --info-size: 37px;              --info-pos-right: -5px;   --info-pos-top: 50%;
  --plus-btn-size: 27px;          --plus-btn-margin-right: 8px;
  --sticker-btn-size: 25px;       
  --ai-btn-size: 27px;            --ai-btn-margin-left: 8px;
  --input-bar-padding-h: 13px;    
  --input-capsule-height: 35px;   
  --input-capsule-max-width: 320px; 
}

/* --- 功能性微调 --- */
.input-btn-sticker { position: relative; left: -40px; top: 0px; }
.input-btn-ai { position: relative !important; left: 25px !important; }

