.chat-header-custom .header-avatar-container, .chat-header-custom .header-avatar, .chat-header-custom [class*="avatar-img"], .chat-header-custom [class*="Avatar"] { display: none !important; visibility: hidden !important; width: 0 !important; height: 0 !important; }

