:root {
  /* ── 对方名字 ── */
  --label-text: "이재민";            /* 🐰🐰 对方气泡上方显示的名字 🐰🐰 */

  /* ── 聊天背景 ── */
  --chat-bg-color: #ffffff;          /* 🐰 聊天背景颜色 */

  /* ── 我方气泡 ── */
  --bubble-me-bg: #f6f6f6;           /* 🐰 我方气泡颜色 */
  --bubble-me-color: #1a1a1a;        /* 🐰 我方气泡文字颜色 */

  /* ── 对方气泡 ── */
  --bubble-them-bg: #97979C;         /* 🐰 对方气泡颜色 */
  --bubble-them-color: #ffffff;      /* 🐰 对方气泡文字颜色 */

  /* ── 顶栏高度 ── */
  --header-height: 80px;             /* 🐰 顶栏高度 */

