  --label-size: 12px;
  --label-weight: 500;
  --label-color: rgba(0, 0, 0, 0.4);
  --label-font: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  --avatar-them-radius: 15px;    
  --avatar-them-size: 38px;  

  /* 图标尺寸 & 位置调节 */
  --back-size: 52px;              --back-pos-left: -12px;   --back-pos-top: 25px;
  --video-size: 50px;             --video-pos-right: 30px;  --video-pos-top: -5px;
  --info-size: 37px;              --info-pos-right: -5px;   --info-pos-top: 50%;
  --plus-btn-size: 27px;          --plus-btn-margin-right: 8px;
  --sticker-btn-size: 25px;       
  --ai-btn-size: 27px;            --ai-btn-margin-left: 8px;
  --input-bar-padding-h: 13px;    
  --input-capsule-height: 35px;   
  --input-capsule-max-width: 320px; 
}

