.input-reply-preview-name { color: rgba(0,0,0,0.9) !important; font-size: 12px !important; font-weight: 600 !important; }
.input-reply-preview-text { color: rgba(0,0,0,0.5) !important; font-size: 12px !important; }
.msg-reply-block { display: none !important; }
