:root { --reply-detached-bg: #d4d4d4; --reply-detached-radius: 12px; --reply-detached-padding: 8px 12px; --reply-detached-border: none; --reply-detached-shadow: none; --reply-detached-text-color: #646464; --reply-detached-name-color: #646464; --reply-detached-max-width: 80%; }
.msg-reply-detached-me { position: relative !important; margin-right: 10px !important; }
.msg-reply-detached-me::after { content: '' !important; position: absolute !important; right: -8px !important; top: 50% !important; transform: translateY(-50%) !important; width: 3px !important; height: 70% !important; background: #d4d4d4 !important; border-radius: 999px !important; pointer-events: none !important; }
