/* --- 不显示小尾巴的消息类型 --- */
/* 表情包、转账、礼物、图片、语音、视频通话、游戏卡、问卷、论坛分享、
   合并转发、情侣邀请、群邀请卡、朋友圈转发 — 一律不要外层贴图 */
.bubble-me-custom.msg-sticker::before,  .bubble-me-custom.msg-sticker::after,
.bubble-them-custom.msg-sticker::before, .bubble-them-custom.msg-sticker::after,

.bubble-me-custom:has(.msg-transfer-card)::before,
.bubble-me-custom:has(.msg-transfer-card)::after,
.bubble-them-custom:has(.msg-transfer-card)::before,
.bubble-them-custom:has(.msg-transfer-card)::after,

.bubble-me-custom:has(.msg-gift-card)::before,
.bubble-me-custom:has(.msg-gift-card)::after,
.bubble-them-custom:has(.msg-gift-card)::before,
.bubble-them-custom:has(.msg-gift-card)::after,

.bubble-me-custom:has(img)::before,   /* 图片消息 */
.bubble-me-custom:has(img)::after,
.bubble-them-custom:has(img)::before,
.bubble-them-custom:has(img)::after,

.bubble-me-custom:has(.msg-voice)::before,
.bubble-me-custom:has(.msg-voice)::after,
.bubble-them-custom:has(.msg-voice)::before,
.bubble-them-custom:has(.msg-voice)::after,

.bubble-me-custom:has(.msg-videocall-log)::before,
.bubble-me-custom:has(.msg-videocall-log)::after,
.bubble-them-custom:has(.msg-videocall-log)::before,
.bubble-them-custom:has(.msg-videocall-log)::after,

.bubble-me-custom:has(.msg-forum-share)::before,
.bubble-me-custom:has(.msg-forum-share)::after,
.bubble-them-custom:has(.msg-forum-share)::before,
.bubble-them-custom:has(.msg-forum-share)::after,

/* 通用兜底：no-padding 的统统是卡片型，不要贴图 */
.bubble-me-custom.no-padding::before,
.bubble-me-custom.no-padding::after,
.bubble-them-custom.no-padding::before,
.bubble-them-custom.no-padding::after {
  display: none !important;
}

 :root {
  /* 1. 调整顶栏的整体高度 (默认一般是 56px 或 60px) */
  /* 👇 把 50px 改成你想要的高度，数字越小越窄 */
  --chat-header-height: 90px; 
}
/* 2. 【极其重要】同步调整消息列表的顶部距离，防止文字被顶栏遮挡 */
.chat-messages-area {
  /* 公式：手机顶部安全区(刘海/灵动岛) + 顶栏高度(50px) + 额外留白(10px) */
  /* 👇 这里的 50px 必须和你上面设置的 --chat-header-height 保持一致！ */
  padding-top: calc(env(safe-area-inset-top, 0px) + 90px + 10px) !important;
}
/* 3. 确保里面的昵称和按钮垂直居中 */
.chat-header-custom {
  display: flex !important;
  align-items: center !important;
  min-height: var(--chat-header-height) !important;
}
 :root {
  /* 我方气泡颜色 - 优雅灰蓝色 */
  --bubble-me-bg: #6E819F;
  --bubble-me-color: #ffffff;
  --bubble-me-bg-gradient: initial;

  /* 对方气泡颜色 - 柔和浅灰紫 */
  --bubble-them-bg: #F1F0F5;
  --bubble-them-color: #1e1e2f;
  --bubble-them-bg-gradient: initial;

  /* 圆形气泡半径 */
  --bubble-me-radius: 20px;
  --bubble-me-radius-first: 20px 20px 5px 20px;
  --bubble-me-radius-mid: 20px 5px 5px 20px;
  --bubble-me-radius-last: 20px 5px 20px 20px;

  --bubble-them-radius: 20px;
  --bubble-them-radius-first: 20px 20px 20px 5px;
  --bubble-them-radius-mid: 5px 20px 20px 5px;
  --bubble-them-radius-last: 5px 20px 20px 20px;

  /* 缩小内边距 */
  --bubble-me-padding: 6px 12px;
  --bubble-them-padding: 6px 12px;

  /* 字体大小 */
  --bubble-me-font-size: 13.5px;
  --bubble-them-font-size: 13.5px;
  --bubble-me-line-height: 1.35;
  --bubble-them-line-height: 1.35;

  /* 阴影 */
  --bubble-me-shadow: 0 1px 1.5px rgba(0,0,0,0.06);
  --bubble-them-shadow: 0 0.5px 1px rgba(0,0,0,0.03);
}
/* 确保气泡边框干净 */
.bubble-me-custom,
.bubble-them-custom {
  border: none !important;
  position: relative !important;
  overflow: visible !important;
}
/* ============================================
   我方气泡 - 右下角装饰贴图
   调整位置：修改 right 和 bottom 数值
   调整大小：修改 width 和 height 数值
   ============================================ */
.bubble-me-custom::after {
  content: "";
  position: absolute;
  /* 👇 调整右下角位置：right（右距离） / bottom（下距离） */
  right: -8px;
  bottom: 0px;
  /* 👇 调整贴图大小：width / height */
  width: 20px;
  height: 20px;
  background: url("https://img.heliar.top/file/1776612747949_retouch_2026041923144965.png") no-repeat center/contain;
  pointer-events: none;
  z-index: 2;
}
/* ============================================
   对方气泡 - 左下角装饰贴图
   调整位置：修改 left 和 bottom 数值
   调整大小：修改 width 和 height 数值
   ============================================ */
.bubble-them-custom::after {
  content: "";
  position: absolute;
  /* 👇 调整左下角位置：left（左距离） / bottom（下距离） */
  left: -8px;
  bottom: 0px;
  /* 👇 调整贴图大小：width / height */
  width: 20px;
  height: 20px;
  background: url("https://img.heliar.top/file/1776612746722_retouch_2026041923160257.png") no-repeat center/contain;
  pointer-events: none;
  z-index: 2;
}
/* 调整消息间距 */
.msg-bubble-wrapper {
  margin-bottom: 6px !important;
}
.msg-bubble-wrapper.is-mid,
.msg-bubble-wrapper.is-first {
  margin-bottom: 2px !important;
}
/* ============================================
   顶栏（Header）定制
   ============================================ */
/* 1. 顶栏背景颜色 - 和对方气泡一样的颜色 (#F1F0F5) */
.chat-header-custom {
  background: #F1F0F5 !important;
  backdrop-filter: none !important;
  border-bottom: 1px solid rgba(0, 0, 0, 0.05) !important;
}
/* 2. 隐藏头像 */
.header-avatar-container {
  display: none !important;
}
/* 3. 昵称居中 - 调整位置 */
.chat-header-title {
  text-align: center !important;
  /* 👇 调整昵称左右位置：修改 margin-left / margin-right */
  margin-left: 0 !important;
  margin-right: 0 !important;
  /* 👇 调整昵称上下位置：修改 margin-top / margin-bottom */
  margin-top: 0 !important;
  margin-bottom: 0 !important;
  display: block !important;
  width: auto !important;
}
/* 确保标题容器居中 */
.header-profile-section {
  position: absolute !important;
  left: 50% !important;
  transform: translateX(-50%) !important;
  display: flex !important;
  flex-direction: column !important;
  align-items: center !important;
  justify-content: center !important;
  width: auto !important;
}
/* 4. 昵称下方加入小字 "◎Online" */
.chat-header-title::after {
  content: "◎Online" !important;
  display: block !important;
  font-size: 11px !important;
  font-weight: 400 !important;
